@pytest.mark.parametrize("precision", ["f32", "f64"]) @pytest.mark.parametrize("policy", ["use", "edges"]) def test_polars_explicit_k2norm_capacity_preserves_small_interiors(precision, policy): dtype = pl.Float32 if precision == "f32" else pl.Float64 values = [-100.0, 0.0, 100.0, 200.0] options = {"max_size": 1200, "scale": "k2norm", "singleton_policy": policy, "precision": precision} if policy == "edges": options["pin_per_side"] = 1 result = pl.DataFrame({"x": pl.Series(values, dtype=dtype)}).select(d=td.tdigest("x", **options)) blob = result.select(td.to_bytes("d")).item() expected = td.TDigest.from_array(values, **options) assert blob == expected.to_bytes() > np.testing.assert_array_equal(expected.means, values) E AssertionError: E Arrays are not equal E E (shapes (3,), (4,) mismatch) E ACTUAL: array([-100., 50., 200.]) E DESIRED: array([-100., 0., 100., 200.])
